async function getAIUnderstanding(request, language) {
  try {
    const response = await openai.responses.create({
      model: "gpt-5-mini",
      input: [
        {
          role: "system",
          content:
            "You are SevaPath, an assistant that helps Indian citizens navigate government services. Analyze the citizen's request and identify their likely need. Do not ask for sensitive personal information. Return only JSON with these fields: need, category, keywords. Keep the response concise. The category should be a simple government-service category such as Transport, Identity, Education, Agriculture, Healthcare, Certificates, Benefits, or Finance. keywords should be an array of short relevant terms."
        },
        {
          role: "user",
          content:
            `Citizen request: ${request}\nPreferred language: ${language}`
        }
      ]
    });

    const text = response.output_text?.trim();

    if (!text) {
      return null;
    }

    return JSON.parse(text);
  } catch (error) {
    console.error("OpenAI understanding error:", error.message);
    return null;
  }
}

function normalize(text = "") {
  return text
    .toLowerCase()
    .replace(/[.,!?;:()[\]{}'"“”‘’]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function calculateScore(text, service) {
  let score = 0;
  const normalizedText = normalize(text);
  const words = normalizedText.split(" ");

  for (const keyword of service.keywords) {
    const key = normalize(keyword);

    if (!key) continue;

    if (normalizedText.includes(key)) {
      if (normalizedText === key) {
        score += 25;
      } else if (key.length >= 10) {
        score += 14;
      } else if (key.length >= 6) {
        score += 10;
      } else {
        score += 6;
      }
    }
  }

  if (service.id === "crop-insurance") {
    const cropWords = [
      "crop",
      "crops",
      "farming",
      "farm",
      "farmer",
      "fasal",
      "फसल",
      "खेती",
      "किसान",
      "पीक",
      "पिक"
    ];

    const damageWords = [
      "damage",
      "damaged",
      "destroyed",
      "destroy",
      "loss",
      "lost",
      "नुकसान",
      "खराब",
      "बर्बाद",
      "नष्ट",
      "नुकसान झाले"
    ];

    const insuranceWords = [
      "insurance",
      "insured",
      "claim",
      "compensation",
      "बीमा",
      "मुआवजा",
      "विमा",
      "भरपाई"
    ];

    const hasCrop = cropWords.some((word) =>
      words.includes(normalize(word))
    );

    const hasDamage = damageWords.some((word) =>
      normalizedText.includes(normalize(word))
    );

    const hasInsurance = insuranceWords.some((word) =>
      normalizedText.includes(normalize(word))
    );

    if (hasCrop) score += 10;
    if (hasDamage) score += 12;
    if (hasInsurance) score += 12;

    if (hasCrop && hasDamage) score += 20;
    if (hasCrop && hasInsurance) score += 20;
    if (hasCrop && hasDamage && hasInsurance) score += 20;
  }

  if (service.id === "aadhaar-update") {
    const aadhaar =
      normalizedText.includes("aadhaar") ||
      normalizedText.includes("aadhar") ||
      normalizedText.includes("आधार");

    const updateWords = [
      "update",
      "change",
      "correction",
      "correct",
      "address",
      "पता",
      "बदलना",
      "सुधार",
      "अपडेट"
    ];

    const hasUpdate = updateWords.some((word) =>
      normalizedText.includes(normalize(word))
    );

    if (aadhaar) score += 15;
    if (hasUpdate) score += 20;
    if (aadhaar && hasUpdate) score += 20;
  }

  if (service.id === "driving-licence") {
    const driving =
      normalizedText.includes("driving") ||
      normalizedText.includes("ड्राइविंग") ||
      normalizedText.includes("ड्रायव्हिंग");

    const newWords = [
      "new",
      "apply",
      "first",
      "पहला",
      "नया",
      "आवेदन",
      "पहिल्यांदा"
    ];

    if (driving) score += 15;

    if (
      newWords.some((word) =>
        normalizedText.includes(normalize(word))
      )
    ) {
      score += 10;
    }
  }

  if (service.id === "driving-renewal") {
    if (
      normalizedText.includes("renew") ||
      normalizedText.includes("renewal") ||
      normalizedText.includes("नवीनीकरण") ||
      normalizedText.includes("रिन्यू") ||
      normalizedText.includes("नूतनीकरण")
    ) {
      score += 25;
    }
  }

  if (service.id === "scholarship") {
    if (
      normalizedText.includes("student") ||
      normalizedText.includes("education") ||
      normalizedText.includes("college") ||
      normalizedText.includes("school") ||
      normalizedText.includes("छात्र") ||
      normalizedText.includes("शिक्षा") ||
      normalizedText.includes("विद्यार्थी") ||
      normalizedText.includes("शिष्यवृत्ती")
    ) {
      score += 8;
    }
  }

  if (service.id === "passport") {
    if (
      normalizedText.includes("travel") ||
      normalizedText.includes("विदेश") ||
      normalizedText.includes("यात्रा") ||
      normalizedText.includes("प्रवास")
    ) {
      score += 8;
    }
  }

  if (service.id === "pension") {
    if (
      normalizedText.includes("old") ||
      normalizedText.includes("senior") ||
      normalizedText.includes("widow") ||
      normalizedText.includes("disability") ||
      normalizedText.includes("वृद्ध") ||
      normalizedText.includes("विधवा") ||
      normalizedText.includes("दिव्यांग")
    ) {
      score += 10;
    }
  }

  return score;
}

function getTopServices(request) {
  const text = normalize(request);

  const scored = services
    .map((service) => ({
      service,
      score: calculateScore(text, service)
    }))
    .filter((item) => item.score > 0)
    .sort((a, b) => b.score - a.score);

  return scored.slice(0, 3);
}

