async function buildResponse(request, language) {
  const selectedLanguage =
    languageNames[language] ? language : "English";

  /*
   * OpenAI provides natural-language understanding.
   * The existing service catalogue remains the source of truth.
   */
  const aiUnderstanding = await getAIUnderstanding(
    request,
    selectedLanguage
  );

  let matches = getTopServices(request);

  /*
   * If the AI identified useful keywords, use them to
   * improve matching without allowing the model to invent
   * government services.
   */
  if (
    aiUnderstanding &&
    Array.isArray(aiUnderstanding.keywords)
  ) {
    const aiText = [
      aiUnderstanding.need || "",
      aiUnderstanding.category || "",
      ...aiUnderstanding.keywords
    ].join(" ");

    const aiMatches = getTopServices(aiText);

    const combined = new Map();

    [...matches, ...aiMatches].forEach((item) => {
      const existing = combined.get(item.service.id);

      if (!existing || item.score > existing.score) {
        combined.set(item.service.id, item);
      }
    });

    matches = [...combined.values()]
      .sort((a, b) => b.score - a.score)
      .slice(0, 3);
  }

  if (matches.length === 0) {
    const fallback = commonTranslations[selectedLanguage];

    return {
      understanding:
        aiUnderstanding?.need ||
        fallback.understanding,

      services: [
        {
          id: "citizen-services",
          name: fallback.citizenName,
          category: fallback.citizenCategory,
          description: fallback.citizenDescription,
          documents: fallback.citizenDocuments,
          online: true,
          why: fallback.citizenWhy,
          nextStep: fallback.citizenNext,
          url: "https://www.india.gov.in/services"
        }
      ],

      checklist: fallback.citizenDocuments,

      nextStep: fallback.citizenNext,

      language: selectedLanguage
    };
  }

  const selected = matches.map((item) => item.service);

  const localizedServices = selected.map((service) =>
    getLocalizedService(service, selectedLanguage)
  );

  const primary = localizedServices[0];

  const checklist = [
    ...new Set(
      localizedServices
        .slice(0, 2)
        .flatMap((service) => service.documents)
    )
  ].slice(0, 6);

  return {
    understanding:
      aiUnderstanding?.need ||
      generateUnderstanding(
        selected[0],
        selectedLanguage
      ),

    services: localizedServices,

    checklist,

    nextStep: primary.nextStep,

    language: selectedLanguage
  };
}

app.post("/api/find-path", async (req, res) => {
  try {
    const { request, language } = req.body;

    console.log("=== FIND PATH DEBUG ===");
    console.log("Request:", request);
    console.log("Language received:", language);

    if (!request || !request.trim()) {
      return res.status(400).json({
        error: "Please describe what you need."
      });
    }

    const result = await buildResponse(
      request,
      language || "English"
    );

    console.log("Language returned:", result.language);
    console.log(
      "First service:",
      result.services?.[0]?.name
    );
    console.log("=======================");

    res.json(result);
  } catch (error) {
    console.error("SevaPath error:", error);

    res.status(500).json({
      error: "Unable to analyze the request."
    });
  }
});

app.get("/api/health", (req, res) => {
  res.json({
    status: "ok",
    service: "SevaPath"
  });
});

const PORT = process.env.PORT || 3001;

app.listen(PORT, "0.0.0.0", () => {
  console.log(
    `SevaPath backend running on port ${PORT}`
  );
});
